E '% -exec bypass%' OR CommandLine ILIKE '% -exe bypass%' OR CommandLine ILIKE '% -ex bypass%' OR CommandLine ILIKE '% -ep bypass%' OR CommandLine ILIKE '% /windowstyle h %' OR CommandLine ILIKE '% /windowstyl h%' OR CommandLine ILIKE '% /windowsty h%' OR CommandLine ILIKE '% /windowst h%' OR CommandLine ILIKE '% /windows h%' OR CommandLine ILIKE '% /windo h%' OR CommandLine ILIKE '% /wind h%' OR CommandLine ILIKE '% /win h%' OR CommandLine ILIKE '% /wi h%' OR CommandLine ILIKE '% /win h %' OR CommandLine ILIKE '% /win hi %' OR CommandLine ILIKE '% /win hid %' OR CommandLine ILIKE '% /win hidd %' OR CommandLine ILIKE '% /win hidde %' OR CommandLine ILIKE '% /NoPr %' OR CommandLine ILIKE '% /NoPro %' OR CommandLine ILIKE '% /NoProf %' OR CommandLine ILIKE '% /NoProfi %' OR CommandLine ILIKE '% /NoProfil %' OR CommandLine ILIKE '% /nonin %' OR CommandLine ILIKE '% /nonint %' OR CommandLine ILIKE '% /noninte %' OR CommandLine ILIKE '% /noninter %' OR CommandLine ILIKE '% /nonintera %' OR CommandLine ILIKE '% /noninterac %' OR CommandLine ILIKE '% /noninteract %' OR CommandLine ILIKE '% /noninteracti %' OR CommandLine ILIKE '% /noninteractiv %' OR CommandLine ILIKE '% /ec %' OR CommandLine ILIKE '% /encodedComman %' OR CommandLine ILIKE '% /encodedComma %' OR CommandLine ILIKE '% /encodedComm %' OR CommandLine ILIKE '% /encodedCom %' OR CommandLine ILIKE '% /encodedCo %' OR CommandLine ILIKE '% /encodedC %' OR CommandLine ILIKE '% /encoded %' OR CommandLine ILIKE '% /encode %' OR CommandLine ILIKE '% /encod %' OR CommandLine ILIKE '% /enco %' OR CommandLine ILIKE '% /en %' OR CommandLine ILIKE '% /executionpolic %' OR CommandLine ILIKE '% /executionpoli %' OR CommandLine ILIKE '% /executionpol %' OR CommandLine ILIKE '% /executionpo %' OR CommandLine ILIKE '% /executionp %' OR CommandLine ILIKE '% /execution bypass%' OR CommandLine ILIKE '% /executio bypass%' OR CommandLine ILIKE '% /executi bypass%' OR CommandLine ILIKE '% /execut bypass%' OR CommandLine ILIKE '% /exec